import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"未濟","description":"周易集解 - 未濟","frontmatter":{"title":"未濟","description":"周易集解 - 未濟"},"headers":[],"relativePath":"zh/classics/jijie/064.md","filePath":"zh/classics/jijie/064.md"}'),l={name:"zh/classics/jijie/064.md"};function n(p,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="未濟" tabindex="-1">未濟 <a class="header-anchor" href="#未濟" aria-label="Permalink to “未濟”">​</a></h1><h2 id="未濟-1" tabindex="-1">未濟 <a class="header-anchor" href="#未濟-1" aria-label="Permalink to “未濟”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>未濟，亨。小狐汔濟，濡其尾，無攸利。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：物不可窮也，故受之以未濟終焉。</p><p>崔憬曰：夫易之為道，窮則變，變則通。而以未濟終者，亦物不可窮也。</p><p>虞翻曰：否二之五也。柔得中，天地交。故亨。濟，成也。六爻皆錯，故稱未濟也。</p><p>虞翻曰：否艮為小狐。汔，幾也。濟，濟渡。狐濟幾度，而濡其尾，未出中也。</p><p>虞翻曰：艮為尾。狐，獸之長尾者也。尾謂二，在坎水中。故濡其尾。失位，故無攸利，不續終也。</p><p>乾寶曰：坎為狐。</p><p>《說文》曰：汔，涸也。</p><p>案：剛柔失正，故未濟也。五居中應剛，故亨也。小狐力弱，汔乃可濟。水既未涸，而乃濟之。故尾濡而無所利也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：未濟亨，柔得中也。小狐汔濟，未出中也。濡其尾，無攸利，不續終也。雖不當位，剛柔應也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>荀爽曰：柔上居五，與陽合同，故亨也。</p><p>虞翻曰：謂二未變，在坎中也。</p><p>乾寶曰：狐，野獸之妖者，以喻祿父。中，謂二也。困而猶處中故也。此以記紂雖亡國，祿父猶得封矣。</p><p>濡其尾，無攸利，不續終也。</p><p>虞翻曰：否陰消陽，至剝終坤，終止則亂，其道窮也。乾五之二，坤殺不行，故不續終也。</p><p>乾寶曰：言祿父不能敬奉天命，以續既終之禮，謂叛而被誅也。</p><p>荀爽曰：雖剛柔相應，而不以正，由未能濟也。</p><p>乾寶曰：六爻皆相應，故微子更得為客也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：火在水上，未濟。君子以慎，辯物居方。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：火性炎上，水性潤下，雖復同體，功不相成，所以未濟也。故君子慎辨物宜，居之以道，令其功用相得，則物咸濟矣。</p><p>虞翻曰：君子，否乾也。艮為慎。辨，辯別也。物謂乾，陽物也，坤陰也；艮為居，坤為方；乾別五以居坤二。故以慎辯物居方也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，濡其尾，吝。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：應在四，故濡其尾。失位，故吝。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：濡其尾，亦不知極也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>案：四在五後，故稱尾。極，中也。謂四居坎中，以濡其尾，是不知極也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，曳其輪，貞吉。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>姚信曰：坎為曳，為輪，兩陰夾陽，輪之象也。二應於五，而隔於四，止則據初，故曳其輪。處中而行，故曰貞吉。</p><p>乾寶曰：坎為輪。離為牛，牛曳輪。上以承五命，猶東蕃之諸侯，共攻三監，以康周道，故曰貞吉也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：九二貞吉，中以行正也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：謂初已正，二動成震，故行正。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，未濟，徵凶，利涉大川。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>荀爽曰：未濟者，未成也。女在外，男在內，婚姻未成。徵上從四則凶。利下從坎，故利涉大川矣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：未濟徵凶，位不當也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>乾寶曰：吉凶者，言乎其得失也。祿父反叛，管蔡與亂，兵連三年，誅及骨肉，故曰未濟徵凶。平剋四國，以濟大難，故曰利涉大川。坎也。以六居三，不當其位，猶周公以臣而君，故流言作矣。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，貞吉，悔亡。震用伐鬼方，三年有賞於大邦。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：動正得位，故吉而悔亡矣。</p><p>虞翻曰：變之震，體師：坤為鬼方。故震用伐鬼方。坤為年，為大邦，陽稱賞，四在坤中，體既濟離三，故三年有賞於大邦。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：貞吉悔亡，志行也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>案：坎為志，震為行，四坎變震，故志行也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，貞吉，無悔。君子之光，有孚，吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：之正則吉，故貞吉無悔。</p><p>虞翻曰：動之乾，離為光，故君子之光也。孚謂二。二變應已，得有之，故有孚吉。坎稱孚也。</p><p>乾寶曰：以六居五，周公攝政之象也，故曰貞吉無悔。制禮作樂，復子明闢。天下乃明其道，乃信其誠。故君子之光，有孚，吉矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：君子之光，其暉吉也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：動之正，乾為大明，故其暉吉也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，有孚於飲酒，無咎。濡其首，有孚失是。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：坎為孚，謂四也。上之三介四，故有孚。飲酒流頤中，故有孚於飲酒。終變之正，故無咎。乾為首，五動首在酒中，失位，故濡其首矣。孚，信。是，正也。六位失政，故有孚失是。謂若殷紂沉湎於酒，以失天下也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：飲酒濡首，亦不知節也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：節，止也。艮為節，飲酒濡首，故不知節矣。</p>',81)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
